def parse_price(s: str) -> float:
    import re
    # Remove dollar sign and commas
    cleaned = re.sub(r'[,$]', '', s)
    # Split into whole number and decimal parts
    if '.' in cleaned:
        whole, decimal = cleaned.split('.')
    else:
        whole = cleaned
        decimal = ''
    # Convert to float
    return float(f'{whole}.{decimal}')

def run_length_encode(s: str) -> str:
    if not s:
        return ''
    result = ''
    current_char = s[0]
    count = 1
    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result += current_char + str(count)
            current_char = char
            count = 1
    result += current_char + str(count)
    return result

